window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-922c5839a9a95943"]={"versions": [{"id": "FIG-922c5839a9a95943", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des LIN-Netzwerkmanagements im Kontext der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht den Kontrollfluss zwischen System- bzw. Zustandsmanagement und dem LIN-NM-Modul beim Hochfahren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager als Aufrufer der Initialisierungsroutine (mit Prozess-/Loop-Symbol gekennzeichnet).\n</li><li><code>«module» LinNm</code>: LIN Network Management als aufgerufenes BSW-Modul.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>LinNm_Init()</code>: Synchrone Initialisierungsfunktion ohne Übergabeparameter vom EcuM an LinNm mit anschließender Rückkehr (gestrichelte Return-Nachricht).\n</li></ul>\n</li><li><strong>Zustandszustände / Invarianten:</strong>\n<ul class=\"fig-list\"><li><code>Bus Sleep Mode</code>: Zustand des LinNm nach bzw. während der Initialisierung.\n</li><li><code>Network Released</code>: Subzustand bzw. Netzwerkzustand des LinNm.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>EcuM</code> initiiert den Kontrollfluss und ruft synchron die Operation <code>LinNm_Init()</code> auf der Lebenslinie von <code>LinNm</code> auf.\n</li><li>Der Aktivierungsbalken an <code>LinNm</code> zeigt die Ausführung der Initialisierungsroutine an.\n</li><li>Nach Abschluss der Initialisierung kehrt die Ausführung via Rückkehrpfeil (gestrichelte Linie) zum aufrufenden <code>EcuM</code> zurück.\n</li><li>Nach dem Aufruf verbleibt bzw. befindet sich das Modul <code>LinNm</code> im Zustand <code>Bus Sleep Mode</code> sowie im Zustand <code>Network Released</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Initialisierung von <code>LinNm</code> erfolgt parameterlos (<code>void</code>). Der Aufrufer <code>EcuM</code> erwartet nach Rückkehr ein betriebsbereites Modul, dessen interner Zustand auf <code>Bus Sleep Mode</code> und <code>Network Released</code> gesetzt ist, bevor weitere Netzwerkaktivitäten oder -anforderungen verarbeitet werden können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cc67996c4ef745c5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des LIN-Netzwerkmanagements im Kontext der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht den Kontrollfluss zwischen System- bzw. Zustandsmanagement und dem LIN-NM-Modul beim Hochfahren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager als Aufrufer der Initialisierungsroutine (mit Prozess-/Loop-Symbol gekennzeichnet).\n</li><li><code>«module» LinNm</code>: LIN Network Management als aufgerufenes BSW-Modul.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>LinNm_Init()</code>: Synchrone Initialisierungsfunktion ohne Übergabeparameter vom EcuM an LinNm mit anschließender Rückkehr (gestrichelte Return-Nachricht).\n</li></ul>\n</li><li><strong>Zustandszustände / Invarianten:</strong>\n<ul class=\"fig-list\"><li><code>Bus Sleep Mode</code>: Zustand des LinNm nach bzw. während der Initialisierung.\n</li><li><code>Network Released</code>: Subzustand bzw. Netzwerkzustand des LinNm.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>EcuM</code> initiiert den Kontrollfluss und ruft synchron die Operation <code>LinNm_Init()</code> auf der Lebenslinie von <code>LinNm</code> auf.\n</li><li>Der Aktivierungsbalken an <code>LinNm</code> zeigt die Ausführung der Initialisierungsroutine an.\n</li><li>Nach Abschluss der Initialisierung kehrt die Ausführung via Rückkehrpfeil (gestrichelte Linie) zum aufrufenden <code>EcuM</code> zurück.\n</li><li>Nach dem Aufruf verbleibt bzw. befindet sich das Modul <code>LinNm</code> im Zustand <code>Bus Sleep Mode</code> sowie im Zustand <code>Network Released</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Initialisierung von <code>LinNm</code> erfolgt parameterlos (<code>void</code>). Der Aufrufer <code>EcuM</code> erwartet nach Rückkehr ein betriebsbereites Modul, dessen interner Zustand auf <code>Bus Sleep Mode</code> und <code>Network Released</code> gesetzt ist, bevor weitere Netzwerkaktivitäten oder -anforderungen verarbeitet werden können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-654da53750adeecb", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Initialisierung des LIN-Netzwerkmanagements im Kontext der AUTOSAR-Basissoftware (Classic Platform). Das Diagramm veranschaulicht den Kontrollfluss zwischen System- bzw. Zustandsmanagement und dem LIN-NM-Modul beim Hochfahren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte Instanzen (Lebenslinien):</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: ECU State Manager als Aufrufer der Initialisierungsroutine (mit Prozess-/Loop-Symbol gekennzeichnet).\n</li><li><code>«module» LinNm</code>: LIN Network Management als aufgerufenes BSW-Modul.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>LinNm_Init(const LinNm_ConfigType*)</code>: Synchrone Initialisierungsfunktion mit Konfigurationszeiger <code>const LinNm_ConfigType*</code> vom EcuM an LinNm mit anschließender Rückkehr (gestrichelte Return-Nachricht).\n</li></ul>\n</li><li><strong>Zustandszustände / Invarianten:</strong>\n<ul class=\"fig-list\"><li><code>Bus Sleep Mode</code>: Zustand des LinNm nach bzw. während der Initialisierung.\n</li><li><code>Network Released</code>: Subzustand bzw. Netzwerkzustand des LinNm.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>EcuM</code> initiiert den Kontrollfluss und ruft synchron die Operation <code>LinNm_Init(const LinNm_ConfigType*)</code> auf der Lebenslinie von <code>LinNm</code> auf.\n</li><li>Der Aktivierungsbalken an <code>LinNm</code> zeigt die Ausführung der Initialisierungsroutine an.\n</li><li>Nach Abschluss der Initialisierung kehrt die Ausführung via Rückkehrpfeil (gestrichelte Linie) zum aufrufenden <code>EcuM</code> zurück.\n</li><li>Nach dem Aufruf verbleibt bzw. befindet sich das Modul <code>LinNm</code> im Zustand <code>Bus Sleep Mode</code> sowie im Zustand <code>Network Released</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Initialisierung von <code>LinNm</code> erfordert die Übergabe eines Zeigers auf die Post-Build- bzw. Initialisierungskonfiguration (<code>const LinNm_ConfigType*</code>). Der Aufrufer <code>EcuM</code> stellt die Konfigurationsstruktur bereit; nach Rückkehr befindet sich das Modul <code>LinNm</code> deterministisch im <code>Bus Sleep Mode</code> und im Zustand <code>Network Released</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-922c5839a9a95943", "to": "FIG-cc67996c4ef745c5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cc67996c4ef745c5", "to": "FIG-654da53750adeecb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aufruf <code>LinNm_Init</code>: Signatur um Konfigurationszeiger <code>const LinNm_ConfigType*</code> ergänzt (vorher parameterlos <code>LinNm_Init()</code>).\n</li></ul>"}]};
